describe('Background Job Notification Toast', () => {
  beforeEach(() => {
    cy.visit('/jobs');
  });

  it('should display success toast notification when background job completes successfully', () => {
    // Intercept the API call for the background job
    cy.intercept('POST', '/api/background-jobs/start').as('startJob');
    cy.intercept('GET', '/api/background-jobs/status').as('getJobStatus');

    // Start the background job
    cy.get('[data-testid="start-job-btn"]').click();
    cy.wait('@startJob');

    // Wait for the job to complete
    cy.wait('@getJobStatus').then((interception) => {
      if (interception.response.statusCode === 200) {
        cy.get('[data-testid="toast-container"]').should('be.visible');
        cy.get('[data-testid="toast-success"]').should('contain', 'Job completed successfully');
        cy.get('[data-testid="toast-success"]').should('have.class', 'toast-success');
        cy.get('[data-testid="toast-success"]').should('be.visible');
        cy.get('[data-testid="toast-success"]').should('contain', 'Your job has finished');
      } else {
        cy.get('[data-testid="toast-container"]').should('not.exist');
        cy.get('[data-testid="error-toast"]').should('be.visible');
        cy.get('[data-testid="error-toast"]').should('contain', 'Job failed');
      }
    });
  });

  it('should display error toast notification when background job fails', () => {
    // Intercept the API call for the background job
    cy.intercept('POST', '/api/background-jobs/start').as('startJob');
    cy.intercept('GET', '/api/background-jobs/status').as('getJobStatus');

    // Start the background job
    cy.get('[data-testid="start-job-btn"]').click();
    cy.wait('@startJob');

    // Simulate job failure
    cy.intercept('GET', '/api/background-jobs/status', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('failedJob');

    // Wait for the failed job status
    cy.wait('@failedJob');

    // Verify error toast is displayed
    cy.get('[data-testid="toast-container"]').should('be.visible');
    cy.get('[data-testid="toast-error"]').should('be.visible');
    cy.get('[data-testid="toast-error"]').should('contain', 'Job failed');
    cy.get('[data-testid="toast-error"]').should('have.class', 'toast-error');

    // Verify success toast is not displayed
    cy.get('[data-testid="toast-success"]').should('not.exist');
  });
});
